"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "checkout",
    "uid": "uid-deployment-checkout"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "768Mi"
        }
      }
    }
  },
  "expected_effect": "Increasing the memory limit should prevent OOM kills by allowing the app to use more memory without being terminated.",
  "rationale": "The current memory limit of 512Mi is insufficient, as evidenced by OOM kills and peak memory reaching 100% of the limit. Raising the limit to 768Mi provides a buffer for increased memory usage without changing the app code, which aligns with the rollout history showing no code changes only metadata updates.",
